def comb_sort(nums):
    n = len(nums)
    gap = len(nums)
    sorted_list = nums.copy()

    while gap > 1 or (gap == 1 and any(sorted_list[i] > sorted_list[i + 1] for i in range(len(sorted_list) - 1))):
        gap = max(1, gap // 3)
        swapped = False
        for i in range(len(sorted_list) - gap):
            if sorted_list[i] > sorted_list[i + gap]:
                sorted_list[i], sorted_list[i + gap] = sorted_list[i + gap], sorted_list[i]
                swapped = True
        if not swapped:
            break
    return sorted_list
```

