import math

def otherside_rightangle(w, h):
    # Calculate the hypotenuse using the Pythagorean theorem
    if w == 0 and h != 0 or h == 0 and w != 0:
        # If one side is 0 and the other is not, the "hypotenuse" would be the non-zero side
        return math.sqrt(w**2 + h**2)
    elif w == 0 and h == 0:
        # This case is invalid for forming a triangle side
        return 0.0
    else:
        # For a right-angled triangle, the hypotenuse is the side opposite the right angle
